#include <bits/stdc++.h>
using namespace std; using E=array<int,5>;using U=uint64_t;const int ps[]={2,3,5,7,11};const int L=24010;
vector<int> dv[L+1];int sp[L+1],om[L+1];E ex[L+1];vector<int> smooth;
U enc(E e){U z=0;for(int i=0;i<5;i++)z|=U(e[i])<<(8*i);return z;} E dec(U z){E e{};for(int i=0;i<5;i++)e[i]=(z>>(8*i))&255;return e;}
int first(int a,int j,int M){for(int d:dv[a])if(a/d<=M/j||om[a/d]<=1)return d;abort();}
bool peel(int a,int b,int M){for(int i=10;i<=12;i++)for(int j=10;j<=12;j++)if(i!=j){int k=33-i-j;int d=first(a,i,M),e=first(b,j,M);if(1ll*d*e<=M/k||om[d]+om[e]<=1)return true;}return false;}
vector<U> sky(vector<U>&v){sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());if(v.empty())return {};E cap{};for(U z:v){E a=dec(z);for(int k=0;k<5;k++)cap[k]=max(cap[k],a[k]);}int st[5]={0,1};for(int k=2;k<5;k++)st[k]=st[k-1]*(cap[k-1]+1);int N=st[4]*(cap[4]+1);vector<int16_t> mx(N,-1);for(U z:v){auto a=dec(z);int idx=0;for(int k=1;k<5;k++)idx+=a[k]*st[k];mx[idx]=max(mx[idx],(int16_t)a[0]);}for(int k=1;k<5;k++){int step=st[k],block=step*(cap[k]+1);for(int b=0;b<N;b+=block)for(int j=cap[k]-1;j>=0;j--)for(int t=0;t<step;t++){int q=b+j*step+t;mx[q]=max(mx[q],mx[q+step]);}}vector<U> out;for(U z:v){auto a=dec(z);int idx=0;for(int k=1;k<5;k++)idx+=a[k]*st[k];if(mx[idx]>a[0])continue;bool dom=false;for(int k=1;k<5;k++)if(a[k]<cap[k]&&mx[idx+st[k]]>=a[0])dom=true;if(!dom)out.push_back(z);}return out;}
int main(int argc,char**argv){int lo=argc>1?atoi(argv[1]):13,hi=argc>2?atoi(argv[2]):L-1;for(int i=2;i<=L;i++)if(!sp[i])for(int j=i;j<=L;j+=i)if(!sp[j])sp[j]=i;for(int i=2;i<=L;i++)om[i]=1+om[i/sp[i]];for(int i=1;i<=L;i++)for(int j=i;j<=L;j+=i)dv[j].push_back(i);for(int a=2;a<=L;a++){int x=a;for(int k=0;k<5;k++)while(x%ps[k]==0){ex[a][k]++;x/=ps[k];}if(x==1)smooth.push_back(a);}
long long total=0;int rows=0;for(int M:smooth){if(M<lo||M>hi||om[M]<2)continue;vector<int> c;for(int a:smooth){if(a>=M)break;if(a>M/12&&om[a]>=2&&!peel(a,M,M))c.push_back(a);}if(c.size()<8)continue;bool changed=true;while(changed){changed=false;vector<int> c2;for(int a:c){int n=0;for(int b:c)if(a!=b&&!peel(a,b,M))n++;if(n>=7)c2.push_back(a);else changed=true;}c.swap(c2);}if(c.size()<8)continue;
vector<vector<U>> dp(9);dp[0]={0};int n=0;for(int a:c){U v=enc(ex[a]);n++;for(int k=min(n,8);k>=1;k--){auto tmp=dp[k];for(U u:dp[k-1])tmp.push_back(u+v);dp[k]=sky(tmp);}}
int f=0;for(U u:dp[8]){E e=dec(u+enc(ex[M]));int cost=0;for(int k=0;k<5;k++){int z=0;for(int j=1;j<=12;j++){z=0;for(int q=M/ps[k];q;q/=ps[k])z+=min(q,j);if(z>=e[k]){cost+=e[k]?j:0;break;}if(j==12)cost+=13;}}if(cost<=12)continue;cout<<M;for(int x:e)cout<<' '<<x;cout<<'\n';f++;}total+=f;rows++;cerr<<M<<" pool="<<c.size()<<" frontier="<<dp[8].size()<<" bad="<<f<<"\n";}
cerr<<"ROWS="<<rows<<" BAD="<<total<<"\n";return 0;}
